mapper.select:
SELECT 
  FROM adv11_book_extr
 WHERE adv11_company_id  = #{companyId}
   AND adv11_std_date    = #{stdDate}
   AND CONCAT(adv11_manage_cd, adv11_manage_nm, adv11_item_cd, adv11_item_nm) ILIKE #{searchText}
 ORDER BY adv11_manage_cd, adv11_item_nm, adv11_item_cd

SELECT TO_CHAR(MAX(adv11_std_date),'yyyy-mm-dd')
  FROM adv11_book_extr
 WHERE adv11_company_id  = #{companyId}
   AND adv11_std_date   <= #{stdDate}

mapper.update:
UPDATE adv11_book_extr
   SET adv11_std_date  = #{req.stdDate},
       adv11_manage_cd = #{req.manageCode},
       adv11_manage_nm = #{req.manageName},
       adv11_item_cd   = #{req.itemCode},
       adv11_item_nm   = #{req.itemName},
       adv11_item_type = #{req.itemType}
 WHERE adv11_book_extr_id = #{req.bookExtrId}
   AND adv11_company_id   = #{companyId}

mapper.delete:
DELETE FROM adv11_book_extr
 WHERE adv11_company_id = #{companyId}
   AND adv11_book_extr_id IN
#{bookExtrId}
